B.XG=new A.b0("mark-lesson-1","path-mark","\ubcf5\uc74c\uc758 \uc2dc\uc791\uacfc \uc989\uac01\uc801\uc778 \uc21c\uc885","\ub9c8\uac00\ubcf5\uc74c 1\uc7a5","\ub9c8\uac00\ubcf5\uc74c\uc740 \uc608\uc218\ub2d8\uc758 \uc0ac\uc5ed\uc744 \ube60\ub974\uac8c \ubcf4\uc5ec\uc8fc\uba70 \ubcf5\uc74c\uc758 \uc2dc\uc791\uc744 \uc120\uc5b8\ud574\uc694. \uc138\ub840 \uc694\ud55c\uc740 \ud68c\uac1c\uc758 \uba54\uc2dc\uc9c0\ub97c \uc804\ud558\uba70 \uc608\uc218\ub2d8\uc758 \uae38\uc744 \uc900\ube44\ud574\uc694. \uc608\uc218\ub2d8\uc740 \uc138\ub840\ub97c \ubc1b\uc73c\uc2dc\uace0 \uace7\ubc14\ub85c \uc2dc\ud5d8\uc744 \uc774\uae30\uc2e0 \ud6c4 \uc0ac\uc5ed\uc744 \uc2dc\uc791\ud558\uc138\uc694. \uc81c\uc790\ub4e4\uc744 \ubd80\ub974\uc2e4 \ub54c \uadf8\ub4e4\uc740 \uc989\uc2dc \ubaa8\ub4e0 \uac83\uc744 \ubc84\ub9ac\uace0 \ub530\ub790\uc5b4\uc694. \uc774 \uc7a5\uc740 \ubcf5\uc74c\uc774 \uc2dc\uc791\ub420 \ub54c \ub098\ud0c0\ub098\ub294 \uc989\uac01\uc801\uc778 \ubc18\uc751\uacfc \uc21c\uc885\uc744 \uac15\uc870\ud574\uc694.","\ub098\ub294 \ud558\ub098\ub2d8\uc758 \ubd80\ub974\uc2ec\uc5d0 \uc989\uc2dc \ubc18\uc751\ud558\uace0 \uc788\ub098\uc694?")
B.Xg=new A.b0("mark-lesson-2","path-mark","\uc8c4\ub97c \uc6a9\uc11c\ud558\uc2dc\ub294 \uc608\uc218\ub2d8\uacfc \uc0c8\ub85c\uc6b4 \uae30\uc900","\ub9c8\uac00\ubcf5\uc74c 2\uc7a5","\uc608\uc218\ub2d8\uc740 \uc911\ud48d\ubcd1\uc790\uc758 \uc8c4\ub97c \uba3c\uc800 \uc0ac\ud558\uc2dc\uba70 \uc601\uc801 \uad8c\uc704\ub97c \ub4dc\ub7ec\ub0b4\uc138\uc694. \uc0ac\ub78c\ub4e4\uc740 \ubcd1\uc758 \uce58\uc720\ub97c \uae30\ub300\ud588\uc9c0\ub9cc \uc608\uc218\ub2d8\uc740 \ub354 \uadfc\ubcf8\uc801\uc778 \ubb38\uc81c\ub97c \ub2e4\ub8e8\uc168\uc5b4\uc694. \uc138\ub9ac \ub808\uc704\ub97c \ubd80\ub974\uc2dc\uba70 \uc8c4\uc778\ub3c4 \ubd80\ub974\uc2dc\ub294 \uc740\ud61c\ub97c \ubcf4\uc5ec\uc8fc\uc138\uc694. \uae08\uc2dd\uacfc \uc548\uc2dd\uc77c\uc5d0 \ub300\ud55c \uac00\ub974\uce68\uc744 \ud1b5\ud574 \uc0c8\ub85c\uc6b4 \uc2dc\ub300\ub97c \uc120\ud3ec\ud558\uc138\uc694. \uc774 \uc7a5\uc740 \uc608\uc218\ub2d8\uc774 \uae30\uc874\uc758 \uc885\uad50\uc801 \ud2c0\uc744 \ub118\uc5b4 \uc0c8\ub85c\uc6b4 \uae30\uc900\uc744 \uc138\uc6b0\uc2dc\ub294 \ubaa8\uc2b5\uc744 \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \ub0b4 \uc8c4\uc758 \uc0ac\ud568\uc744 \uc608\uc218\ub2d8\uaed8 \ub9e1\uae30\uace0 \uc788\ub098\uc694?")
B.XS=new A.b0("mark-lesson-3","path-mark","\uc608\uc218\ub2d8\uc758 \uad8c\uc704\uc640 \ucc38\ub41c \uac00\uc871","\ub9c8\uac00\ubcf5\uc74c 3\uc7a5","\uc608\uc218\ub2d8\uc740 \uc548\uc2dd\uc77c\uc5d0 \ubcd1\uc744 \uace0\uce58\uc2dc\uba70 \uc0ac\ub78c\uc744 \uc0b4\ub9ac\ub294 \uac83\uc774 \ub354 \uc911\uc694\ud558\ub2e4\uace0 \uac00\ub974\uce58\uc138\uc694. \ub9ce\uc740 \ubcd1\uc790\ub97c \uace0\uce58\uc2dc\uba70 \uad8c\uc704\ub97c \ub4dc\ub7ec\ub0b4\uc2dc\uace0 \uc5f4\ub450 \uc81c\uc790\ub97c \uc138\uc6b0\uc138\uc694. \uc885\uad50 \uc9c0\ub3c4\uc790\ub4e4\uc740 \uc608\uc218\ub2d8\uc744 \uc624\ud574\ud558\uace0 \ube44\ub09c\ud574\uc694. \uc608\uc218\ub2d8\uc740 \ud558\ub098\ub2d8\uc758 \ub73b\uc744 \ud589\ud558\ub294 \uc0ac\ub78c\uc774 \uc9c4\uc9dc \uac00\uc871\uc774\ub77c\uace0 \ub9d0\uc500\ud558\uc138\uc694. \uc774 \uc7a5\uc740 \uad00\uacc4\uc758 \uae30\uc900\uc774 \ud608\uc5f0\uc774 \uc544\ub2c8\ub77c \ud558\ub098\ub2d8\uacfc\uc758 \uad00\uacc4\uc784\uc744 \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \ud558\ub098\ub2d8\uc758 \ub73b\uc744 \uc911\uc2ec\uc73c\ub85c \uc0b4\uace0 \uc788\ub098\uc694?")
B.WU=new A.b0("mark-lesson-4","path-mark","\ub9d0\uc500\uc744 \ubc1b\uc544\ub4e4\uc774\ub294 \ub9c8\uc74c","\ub9c8\uac00\ubcf5\uc74c 4\uc7a5","\uc608\uc218\ub2d8\uc740 \uc528 \ubfcc\ub9ac\ub294 \ube44\uc720\ub97c \ud1b5\ud574 \uc0ac\ub78c\uc758 \ub9c8\uc74c \uc0c1\ud0dc\uc5d0 \ub530\ub77c \ub9d0\uc500\uc774 \ub2e4\ub974\uac8c \ubc1b\uc544\ub4e4\uc5ec\uc9c4\ub2e4\uace0 \uac00\ub974\uce58\uc138\uc694. \uc5b4\ub5a4 \ub9c8\uc74c\uc740 \ub9d0\uc500\uc744 \uae08\ubc29 \uc783\uc5b4\ubc84\ub9ac\uace0, \uc5b4\ub5a4 \ub9c8\uc74c\uc740 \uc5b4\ub824\uc6c0 \ub54c\ubb38\uc5d0 \ud3ec\uae30\ud574\uc694. \uadf8\ub7ec\ub098 \uc900\ube44\ub41c \ub9c8\uc74c\uc740 \ub9d0\uc500\uc744 \ubc1b\uc544\ub4e4\uc774\uace0 \uc5f4\ub9e4\ub97c \ub9fa\uc5b4\uc694. \ub610\ud55c \ub4f1\ubd88\uc758 \ube44\uc720\ub97c \ud1b5\ud574 \ub4dc\ub7ec\ub098\ub294 \ubbff\uc74c\uc758 \uc911\uc694\uc131\uc744 \ub9d0\uc500\ud558\uc138\uc694. \uc774 \uc7a5\uc740 \ub9c8\uc74c\uc758 \uc0c1\ud0dc\uac00 \uc2e0\uc559\uc758 \uacb0\uacfc\ub97c \uacb0\uc815\ud55c\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \uc5b4\ub5a4 \ub9c8\uc74c\uc73c\ub85c \ub9d0\uc500\uc744 \ub4e3\uace0 \uc788\ub098\uc694?")
B.XR=new A.b0("mark-lesson-5","path-mark","\ubbff\uc74c\uc73c\ub85c \ub098\uc544\uac00\ub294 \uc0b6","\ub9c8\uac00\ubcf5\uc74c 5\uc7a5","\uc608\uc218\ub2d8\uc740 \uadc0\uc2e0 \ub4e4\ub9b0 \uc0ac\ub78c\uc744 \uc790\uc720\ub86d\uac8c \ud558\uc2dc\uace0, \ubcd1\ub4e0 \uc5ec\uc778\uc744 \uace0\uce58\uc2dc\uba70 \uc8fd\uc740 \uc18c\ub140\ub97c \uc0b4\ub9ac\uc138\uc694. \uac01\uac01\uc758 \uc0c1\ud669\uc5d0\uc11c \ubbff\uc74c\uc774 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud574\uc694. \uc0ac\ub78c\ub4e4\uc740 \ub450\ub824\uc6cc\ud588\uc9c0\ub9cc, \uc608\uc218\ub2d8\uc740 \ubbff\uc74c\uc744 \uac15\uc870\ud558\uc138\uc694. \ubbff\uc74c\uc740 \ub2e8\uc21c\ud55c \uc0dd\uac01\uc774 \uc544\ub2c8\ub77c \ud589\ub3d9\uc73c\ub85c \ub098\ud0c0\ub098\uc694. \uc774 \uc7a5\uc740 \uc608\uc218\ub2d8\uaed8 \ub098\uc544\uac00\ub294 \ubbff\uc74c\uc774 \uc0b6\uc744 \ubcc0\ud654\uc2dc\ud0a8\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \ub450\ub824\uc6c0\ubcf4\ub2e4 \ubbff\uc74c\uc744 \uc120\ud0dd\ud558\uace0 \uc788\ub098\uc694?")
B.WW=new A.b0("mark-lesson-6","path-mark","\ubd88\uc2e0\uacfc \uc21c\uc885\uc758 \ucc28\uc774","\ub9c8\uac00\ubcf5\uc74c 6\uc7a5","\uc608\uc218\ub2d8\uc740 \uace0\ud5a5\uc5d0\uc11c \ubbff\uc9c0 \uc54a\ub294 \uc0ac\ub78c\ub4e4\ub85c \uc778\ud574 \ub9ce\uc740 \uc77c\uc744 \ud558\uc9c0 \uc54a\uc73c\uc138\uc694. \uc81c\uc790\ub4e4\uc744 \ubcf4\ub0b4\uc2e4 \ub54c \uc544\ubb34\uac83\ub3c4 \uc758\uc9c0\ud558\uc9c0 \ub9d0\uace0 \ud558\ub098\ub2d8\ub9cc \uc758\uc9c0\ud558\ub77c\uace0 \ud558\uc138\uc694. \uc624\ubcd1\uc774\uc5b4 \uc0ac\uac74\uc744 \ud1b5\ud574 \ubd80\uc871\ud568 \uc18d\uc5d0\uc11c\ub3c4 \ud558\ub098\ub2d8\uc758 \ub2a5\ub825\uc774 \ub4dc\ub7ec\ub098\uc694. \ud558\uc9c0\ub9cc \uc81c\uc790\ub4e4\uc740 \uc5ec\uc804\ud788 \uc774\ud574\ud558\uc9c0 \ubabb\ud558\uace0 \uc788\uc5b4\uc694. \uc774 \uc7a5\uc740 \ubbff\uc74c\uacfc \ubd88\uc2e0\uc758 \ucc28\uc774\ub97c \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \ud558\ub098\ub2d8\uc744 \ubbff\uace0 \uc788\ub098\uc694, \uc544\ub2c8\uba74 \uc758\uc2ec\ud558\uace0 \uc788\ub098\uc694?")
B.Xt=new A.b0("mark-lesson-7","path-mark","\ub9c8\uc74c\uc5d0\uc11c \uc2dc\uc791\ub418\ub294 \uc2e0\uc559","\ub9c8\uac00\ubcf5\uc74c 7\uc7a5","\uc608\uc218\ub2d8\uc740 \uc190 \uc53b\ub294 \uaddc\ub840\ub97c \ub450\uace0 \ud615\uc2dd\uc801\uc778 \uc2e0\uc559\uc744 \ucc45\ub9dd\ud558\uc138\uc694. \uc0ac\ub78c\uc744 \ub354\ub7fd\uac8c \ud558\ub294 \uac83\uc740 \uc678\uc801\uc778 \uac83\uc774 \uc544\ub2c8\ub77c \ub9c8\uc74c\uc5d0\uc11c \ub098\uc624\ub294 \uac83\uc774\ub77c\uace0 \ub9d0\uc500\ud558\uc138\uc694. \ub9d0\uacfc \ud589\ub3d9\uc758 \ubfcc\ub9ac\ub294 \ub9c8\uc74c\uc5d0 \uc788\uc5b4\uc694. \ub610\ud55c \uc774\ubc29 \uc5ec\uc778\uc758 \ubbff\uc74c\uc744 \ud1b5\ud574 \uc9c4\uc9dc \ubbff\uc74c\uc774 \ubb34\uc5c7\uc778\uc9c0 \ubcf4\uc5ec\uc8fc\uc138\uc694. \uc774 \uc7a5\uc740 \uc2e0\uc559\uc758 \uc911\uc2ec\uc774 \uac89\uc774 \uc544\ub2c8\ub77c \ub9c8\uc74c\uc774\ub77c\ub294 \uac83\uc744 \uac15\uc870\ud574\uc694.","\ub098\ub294 \uac89\ubcf4\ub2e4 \ub9c8\uc74c\uc744 \ub354 \uc911\uc694\ud558\uac8c \uc5ec\uae30\uace0 \uc788\ub098\uc694?")
B.X3=new A.b0("mark-lesson-8","path-mark","\uc601\uc801\uc778 \ub208\uacfc \ubbff\uc74c","\ub9c8\uac00\ubcf5\uc74c 8\uc7a5",'\uc608\uc218\ub2d8\uc740 \ub610 \ud55c \ubc88 \ub9ce\uc740 \uc0ac\ub78c\uc744 \uba39\uc774\uc2dc\uace0 \uc81c\uc790\ub4e4\uc5d0\uac8c \ubbff\uc74c\uc744 \uac00\ub974\uce58\uc138\uc694. \uadf8\ub7ec\ub098 \uc81c\uc790\ub4e4\uc740 \uc5ec\uc804\ud788 \uae68\ub2eb\uc9c0 \ubabb\ud558\uace0 \uc788\uc5b4\uc694. \uc608\uc218\ub2d8\uc740 "\ub108\ud76c\uac00 \uc544\uc9c1\ub3c4 \uae68\ub2eb\uc9c0 \ubabb\ud558\ub290\ub0d0"\uace0 \ub9d0\uc500\ud558\uc138\uc694. \ubca0\ub4dc\ub85c\ub294 \uc608\uc218\ub2d8\uc744 \uadf8\ub9ac\uc2a4\ub3c4\ub85c \uace0\ubc31\ud558\uc9c0\ub9cc, \uc774\ud6c4 \uc2ed\uc790\uac00\ub97c \uc774\ud574\ud558\uc9c0 \ubabb\ud574\uc694. \uc774 \uc7a5\uc740 \ubbff\uc74c\uc774 \ub2e8\uc21c\ud55c \uc774\ud574\uac00 \uc544\ub2c8\ub77c \uae4a\uc740 \uae68\ub2ec\uc74c\uc774 \ud544\uc694\ud568\uc744 \ubcf4\uc5ec\uc918\uc694.',"\ub098\ub294 \ud558\ub098\ub2d8\uc744 \uc81c\ub300\ub85c \uc774\ud574\ud558\uace0 \uc788\ub098\uc694?")
B.XE=new A.b0("mark-lesson-9","path-mark","\ubbff\uc74c\uacfc \uacb8\uc190","\ub9c8\uac00\ubcf5\uc74c 9\uc7a5",'\uc608\uc218\ub2d8\uc740 \ubcc0\ud654\uc0b0\uc5d0\uc11c \uc601\uad11\uc744 \ubcf4\uc774\uc2dc\uace0 \uc81c\uc790\ub4e4\uc5d0\uac8c \ud558\ub098\ub2d8\uc758 \uc74c\uc131\uc744 \ub4e3\uac8c \ud558\uc138\uc694. \uc774\ud6c4 \uc81c\uc790\ub4e4\uc774 \uadc0\uc2e0\uc744 \ucad3\uc544\ub0b4\uc9c0 \ubabb\ud558\uc790 \ubbff\uc74c\uc758 \ubd80\uc871\uc744 \uc9c0\uc801\ud558\uc138\uc694. "\ubbff\ub294 \uc790\uc5d0\uac8c\ub294 \ub2a5\uce58 \ubabb\ud560 \uc77c\uc774 \uc5c6\ub2e4"\uace0 \ub9d0\uc500\ud558\uc138\uc694. \ub610\ud55c \ub204\uac00 \ud070 \uc790\uc778\uc9c0 \ub2e4\ud22c\ub294 \uc81c\uc790\ub4e4\uc5d0\uac8c \uc12c\uae40\uacfc \uacb8\uc190\uc744 \uac00\ub974\uce58\uc138\uc694. \uc774 \uc7a5\uc740 \ubbff\uc74c\uacfc \uacb8\uc190\uc774 \ud568\uaed8 \uac00\uc57c \ud568\uc744 \ubcf4\uc5ec\uc918\uc694.',"\ub098\ub294 \ud558\ub098\ub2d8\uc744 \uc5bc\ub9c8\ub098 \ubbff\uace0 \uc788\ub098\uc694?")
B.WS=new A.b0("mark-lesson-10","path-mark","\ud558\ub098\ub2d8 \ub098\ub77c\uc640 \uc81c\uc790\uc758 \uacb0\ub2e8","\ub9c8\uac00\ubcf5\uc74c 10\uc7a5","\uc608\uc218\ub2d8\uc740 \uacb0\ud63c\uacfc \uc774\ud63c\uc5d0 \ub300\ud574 \ub9d0\uc500\ud558\uc2dc\uba70 \ud558\ub098\ub2d8\uc758 \ub73b\uc744 \uac15\uc870\ud558\uc138\uc694. \uc5b4\ub9b0\uc544\uc774\uc640 \uac19\uc740 \uc790\uac00 \ud558\ub098\ub2d8 \ub098\ub77c\ub97c \ubc1b\ub294\ub2e4\uace0 \ud558\uc2dc\uba70 \uacb8\uc190\uc744 \uac00\ub974\uce58\uc138\uc694. \ubd80\uc790 \uccad\ub144\uc740 \uc608\uc218\ub2d8\uc758 \ubd80\ub974\uc2ec\uc744 \ub4e3\uace0\ub3c4 \uc7ac\ubb3c\uc744 \ub0b4\ub824\ub193\uc9c0 \ubabb\ud574\uc694. \uc608\uc218\ub2d8\uc740 \ud558\ub098\ub2d8 \ub098\ub77c\uc5d0 \ub4e4\uc5b4\uac00\ub294 \uac83\uc774 \uc27d\uc9c0 \uc54a\uc74c\uc744 \ub9d0\uc500\ud558\uc138\uc694. \uc774 \uc7a5\uc740 \ud558\ub098\ub2d8\uc744 \ub530\ub974\uae30 \uc704\ud55c \uacb0\ub2e8\uacfc \uc6b0\uc120\uc21c\uc704\ub97c \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \ud558\ub098\ub2d8\ubcf4\ub2e4 \ub354 \ubd99\uc7a1\uace0 \uc788\ub294 \uac83\uc774 \uc788\ub098\uc694?")
B.XH=new A.b0("mark-lesson-11","path-mark","\ubbff\uc74c\uacfc \uc5f4\ub9e4","\ub9c8\uac00\ubcf5\uc74c 11\uc7a5","\uc608\uc218\ub2d8\uc740 \uc608\ub8e8\uc0b4\ub818\uc5d0 \uc785\uc131\ud558\uc2dc\uace0 \uc131\uc804\uc744 \uc815\uacb0\ud558\uac8c \ud558\uc138\uc694. \ubb34\ud654\uacfc\ub098\ubb34\ub97c \ud1b5\ud574 \uc5f4\ub9e4 \uc5c6\ub294 \uc2e0\uc559\uc744 \ucc45\ub9dd\ud558\uc138\uc694. \ub610\ud55c \ubbff\uc74c\uc73c\ub85c \uae30\ub3c4\ud560 \uac83\uc744 \uac00\ub974\uce58\uc138\uc694. \ud558\ub098\ub2d8\uc744 \ud5a5\ud55c \uc9c4\uc9dc \uc2e0\uc559\uc740 \uc5f4\ub9e4\ub85c \ub4dc\ub7ec\ub098\uc694. \uc774 \uc7a5\uc740 \ubbff\uc74c\uacfc \uc2e4\uc81c \uc0b6\uc758 \uc5f0\uacb0\uc744 \uac15\uc870\ud574\uc694.","\ub098\ub294 \uc5f4\ub9e4 \uc788\ub294 \uc0b6\uc744 \uc0b4\uace0 \uc788\ub098\uc694?")
